#define _GNU_SOURCE
#include <assert.h>
#include <dlfcn.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include "witprobe_wasmtime.h"

typedef struct {
  void *library;
  wasmtime_error_t *(*open)(witprobe_wasmtime **);
  wasmtime_error_t *(*evaluate)(witprobe_wasmtime *, const witprobe_tree_t *, uint32_t *);
  void (*close)(witprobe_wasmtime *);
  void (*error_delete)(wasmtime_error_t *);
} api;

static api load(const char *path) {
  api value = {0};
  value.library = dlopen(path, RTLD_NOW | RTLD_LOCAL);
  if (!value.library) { fprintf(stderr, "%s\n", dlerror()); return value; }
#define SYMBOL(field, name) do { void *p = dlsym(value.library, name); assert(p); memcpy(&value.field, &p, sizeof(value.field)); } while (0)
  SYMBOL(open, "witprobe_wasmtime_open");
  SYMBOL(evaluate, "witprobe_wasmtime_value_evaluate");
  SYMBOL(close, "witprobe_wasmtime_close");
  SYMBOL(error_delete, "wasmtime_error_delete");
#undef SYMBOL
  return value;
}

int main(int argc, char **argv) {
  assert(argc == 2 || argc == 3);
  api first = load(argv[1]); assert(first.library);
  witprobe_wasmtime *a = NULL; assert(!first.open(&a));
  witprobe_tree_t input = {.kind = WITPROBE_TREE_T_KIND_LEAF, .cases.leaf.value = 1};
  uint32_t before = 0; assert(!first.evaluate(a, &input, &before));
  if (argc == 2) { printf("{\"value\":%u}\n", before); first.close(a); dlclose(first.library); return 0; }
  api second = load(argv[2]);
  witprobe_wasmtime *b = NULL;
  uint32_t other = UINT32_C(0xabcdef), after = 0;
  wasmtime_error_t *error = second.library ? second.open(&b) : NULL;
  if (second.library && !error) error = second.evaluate(b, &input, &other);
  int rejected = !second.library || error != NULL;
  if (error) { assert(other == UINT32_C(0xabcdef)); second.error_delete(error); }
  assert(!first.evaluate(a, &input, &after)); assert(after == before);
  if (b) second.close(b);
  if (second.library) dlclose(second.library);
  first.close(a); dlclose(first.library);
  printf("{\"first\":%u,\"secondRejected\":%s,\"second\":%u,\"firstAfter\":%u}\n", before, rejected ? "true" : "false", other, after);
}

